package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;import java.util.*;
/** Persistent living-world population registry. Population identity/location/availability is active; combat stats require a compiled statblock. */
public final class WorldPopulationEngine{
 private WorldPopulationEngine(){}
 public static JSONObject empty(){JSONObject o=new JSONObject();try{o.put("schema",1).put("actors",new JSONObject()).put("revision",0);}catch(Exception ignored){}return o;}
 public static JSONObject upsert(JSONObject state,JSONObject actor,int day){JSONObject o=copy(state);try{if(actor==null)return o;String id=actor.optString("id").trim();if(id.length()==0)return o;JSONObject all=obj(o,"actors"),old=all.optJSONObject(id),a=old==null?new JSONObject():copy(old);String[] keys={"name","kind","location","faction","attitude","occupation","source_book","statblock_id"};for(String k:keys)if(actor.has(k))a.put(k,actor.opt(k));if(!a.has("status"))a.put("status","active");a.put("id",id).put("last_day",Math.max(1,day));a=CompiledStatblockEngine.bindActor(a);all.put(id,a);o.put("actors",all).put("revision",o.optInt("revision",0)+1);}catch(Exception ignored){}return o;}
 public static JSONObject spawnStatblock(JSONObject state,String actorId,String statblockId,String name,String location,String faction,String attitude,int day){if(actorId==null||actorId.trim().isEmpty())throw new IllegalArgumentException("actor id required");if(statblockId==null||!CompiledStatblockEngine.has(statblockId.trim()))throw new IllegalArgumentException("authorized statblock required");JSONObject actor=new JSONObject();try{JSONObject profile=CompiledStatblockEngine.runtimeProfile(statblockId.trim());actor.put("id",actorId.trim()).put("name",name==null||name.trim().isEmpty()?statblockId:name.trim()).put("kind","statblock_actor").put("location",location==null?"":location.trim()).put("faction",faction==null?"":faction.trim()).put("attitude",attitude==null?"":attitude.trim()).put("statblock_id",statblockId.trim()).put("runtime_tier",profile.optJSONObject("completeness")==null?"combat_core":profile.optJSONObject("completeness").optString("tier","combat_core")).put("spawn_day",Math.max(1,day));}catch(Exception e){throw new IllegalArgumentException(e.getMessage());}return upsert(state,actor,day);}
 public static JSONObject move(JSONObject state,String id,String location,int day){JSONObject patch=new JSONObject();try{patch.put("id",id).put("location",location);}catch(Exception ignored){}return upsert(state,patch,day);}
 public static JSONObject setStatus(JSONObject state,String id,String status,int day){JSONObject patch=new JSONObject();try{patch.put("id",id).put("status",status);}catch(Exception ignored){}JSONObject o=upsert(state,patch,day);try{JSONObject a=obj(o,"actors").optJSONObject(id);if(a!=null)a.put("status",status==null?"active":status);}catch(Exception ignored){}return o;}
 public static JSONArray at(JSONObject state,String location){JSONArray out=new JSONArray();try{JSONObject all=obj(state,"actors");Iterator<String>it=all.keys();while(it.hasNext()){JSONObject a=all.optJSONObject(it.next());if(a!=null&&location.equals(a.optString("location"))&&!"removed".equals(a.optString("status")))out.put(copy(a));}}catch(Exception ignored){}return out;}
 public static JSONObject get(JSONObject state,String id){try{JSONObject a=obj(state,"actors").optJSONObject(id);return a==null?new JSONObject():copy(a);}catch(Exception e){return new JSONObject();}}
 private static JSONObject obj(JSONObject o,String k){JSONObject x=o==null?null:o.optJSONObject(k);return x==null?new JSONObject():x;}private static JSONObject copy(JSONObject o){try{return o==null?new JSONObject():new JSONObject(o.toString());}catch(Exception e){return new JSONObject();}}
}
